export type SocketStatus = "connecting" | "live" | "reconnecting" | "disconnected";

export const RECONNECT_INITIAL_MS = 1_000;
export const RECONNECT_MAX_MS = 30_000;
export const RECONNECT_JITTER_MS = 500;
