export function reconnectDelay(attempt: number, random = Math.random): number {
  const exponential = Math.min(RECONNECT_INITIAL_MS * (2 ** attempt), RECONNECT_MAX_MS);
  const jitter = Math.round((random() * 2 - 1) * RECONNECT_JITTER_MS);
  return Math.max(0, exponential + jitter);
}

